layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = uTime - aT; if (u < 0. || u > 1.10){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vP = position.xy;
      if (aK < .5){ vP = position.xy*2.6; vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.2, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.3; mv.xy += position.xy*.6; gl_Position = projectionMatrix*mv; }   /* Fear pulse on the torso (billboard), not the ground */
      else if (aK < 1.5){ vec3 f = cameraPosition - aO; f.y = 0.; f = normalize(f); vec3 rt = vec3(f.z, 0., -f.x);
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + rt*position.x*.55 + vec3(0., (position.y*.5 + .5)*2.3, 0.), 1.); }
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.2, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.3; float S = 1.5; mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv; }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){
      float lum = 0., hot = 0., t = vU/1.10;
      if (vK < .5){
        /* Fear: a big jagged shockwave bursts OUT from the target (double ring, long barbs), flickering */
        float r = length(vP), a = atan(vP.y, vP.x), e = 1. - pow(1. - clamp(vU/.35, 0., 1.), 3.);
        float jag = .06*sin(a*13. + vU*20.)*sin(a*7. - 3.) ;
        float R = .3 + 2.*e + jag, R2 = .2 + 1.45*e - jag*.7;
        float f = (vU < .05 ? 2. : 1.)*(1. - smoothstep(.35, .75, t))*(.8 + .2*sin(vU*60.));
        lum += (exp(-pow(abs(r - R)/.03, 2.2)) + exp(-pow(abs(r - R2)/.02, 2.2))*.6)*f; hot += lcore(r - R, .008)*f*.7;
        float a8 = mod(a + .2, .524) - .262, ax = r*cos(a8) - R, ay = abs(r*sin(a8)), bl = .35;
        float barb = smoothstep(.02, .0, ay - .07*clamp(1. - ax/bl, 0., 1.))*step(0., ax)*step(ax, bl);
        lum += barb*f*1.1; hot += barb*f*.35;
        lum += smoothstep(R, R - .5, r)*smoothstep(R - 1.2, R - .5, r)*.12*f;                   /* cold wash behind the front */
        lum *= smoothstep(2.6, 2.4, r); hot *= smoothstep(2.6, 2.4, r);
      } else if (vK < 1.5){
        // Heal: thin streaks rise from the feet in a soft ease-out and open outward a little as they go
        float x = vP.x, y = vP.y*.5 + .5, k = 1. - pow(1. - clamp(vU/.55, 0., 1.), 3.), f = 1. - smoothstep(.5, 1., t);
        for (int i=0;i<6;i++){
          float fi = float(i), ox = (h1(fi) - .5)*1.1*(.4 + .6*y), dl = h1(fi + 3.)*.12;
          float kk = 1. - pow(1. - clamp((vU - dl)/.55, 0., 1.), 3.), head = kk*1.05, tail = head - .35;
          lum += exp(-pow((x - ox)/.03, 2.))*smoothstep(tail, tail + .2, y)*smoothstep(head + .02, head - .1, y)*(.6 + .4*h1(fi + 9.));
          vec2 sp = vec2(x - ox*.8, y - head*.9);                           // a small sparkle riding each streak
          float sa = atan(sp.y, sp.x), sr = length(sp*vec2(1., 2.3));
          lum += pow(abs(cos(sa*2.)), 12.)*exp(-sr*40.)*.8;
        }
        lum *= f*smoothstep(1., .75, abs(x))*smoothstep(1., .85, y); hot = lum*.3;
      } else {
        /* damage: a huge eye tears open on the chest and stares (slit pupil), then snaps shut with a pop; screaming
           wisps burst out of it (icon's ghosts) with a shock ring */
        vec2 p = vP/1.5; float r = length(p), a = atan(p.y, p.x);
        float k = clamp(vU/.3, 0., 1.), op = sin(3.14159*min(k*1.7, 1.))*(1. - k*k*k*k), h = .04 + .5*op;
        float eyeD = max(length(p - vec2(0., -(.62 - h))) - .62, length(p - vec2(0., .62 - h)) - .62);
        float live = step(vU, .3);
        vec2 sp = p*vec2(1., .33/max(op, .05)); float slit = exp(-pow((length(sp) - .06)/.012, 2.))*smoothstep(.02, -.04, eyeD)*op;
        lum += (exp(-pow(eyeD/.025, 2.))*1.3 + exp(-r*r*40.)*op*.5)*live; hot += (slit*2. + exp(-pow(eyeD/.008, 2.))*.5)*live;
        float pop = vU >= .3 && vU < .333 ? 1. : 0., after = vU > .3 ? exp(-(vU - .3)*10.) : 0.;
        lum += exp(-p.y*p.y*300. - p.x*p.x*3.)*(pop*3. + after); hot += exp(-r*r*150.)*(pop*3. + after);
        float tw = clamp((vU - .3)/.7, 0., 1.), tf = clamp((vU - .3)/.35, 0., 1.);   /* orbs fade 50% faster */
        if (vU > .3){
          float sr = mix(.1, .95, 1. - pow(1. - tw, 2.)); float jr = sr*(1. + .12*sin(a*9. + vU*14.)); /* no shock ring */
          for (int i=0;i<7;i++){ float fi = float(i), ga = fi*.898 + .4 + .3*sin(vU*3. + fi), gd = mix(.1, .85, 1. - pow(1. - tw, 1.6));
            vec2 dir = vec2(cos(ga), sin(ga)), nrm = vec2(-dir.y, dir.x); vec2 q = p - dir*gd;
            float along = dot(q, dir), across = dot(q, nrm) + .05*sin(along*18. - vU*25. + fi);
            float tail = exp(-across*across/(.0012 + .004*max(-along, 0.)))*smoothstep(-.35, 0., along)*step(along, .05);
            vec2 hq = q - dir*.01; float head = exp(-dot(hq, hq)*1600.);   /* smaller orbs */
            float mouth = exp(-dot(hq + dir*.012, hq + dir*.012)*9000.);                          /* the gaping mouth reads as a dark notch */
            lum += head*1.2*(1. - tf); hot += head*.8*(1. - tf); }   /* only the orbs, no star-shaped tails */
        }
        lum *= smoothstep(1., .9, r); hot *= smoothstep(1., .9, r);
      }
      vec3 o = uOrange*lum + mix(uGold, vec3(1.), .5)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
